import { createClient } from "@clickhouse/client";

const CLICKHOUSE_URL = process.env.CLICKHOUSE_URL ?? "http://localhost:8123";
const REDPANDA_BROKER = process.env.REDPANDA_BROKER ?? "localhost:9092";

const client = createClient({ url: CLICKHOUSE_URL });

async function createKafkaSourceTable(): Promise<void> {
  await client.command({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.metrics_queue (
        host_id String,
        metric_name String,
        value Float64,
        ts String
      ) ENGINE = Kafka()
      SETTINGS
        kafka_broker_list = '${REDPANDA_BROKER}',
        kafka_topic_list = 'metrics',
        kafka_group_name = 'clickhouse_consumer',
        kafka_format = 'JSONEachRow',
        kafka_num_consumers = 2,
        kafka_skip_broken_messages = 1
    `,
  });
}

async function createMaterializedView(): Promise<void> {
  await client.command({
    query: `
      CREATE MATERIALIZED VIEW IF NOT EXISTS analytics.metrics_mv
      TO analytics.realtime_metrics AS
      SELECT
        host_id,
        metric_name,
        value,
        parseDateTime64BestEffort(ts) AS ts
      FROM analytics.metrics_queue
    `,
  });
}

async function main(): Promise<void> {
  await createKafkaSourceTable();
  await createMaterializedView();
}

main().catch((err: unknown) => {
  process.stderr.write(`Pipeline setup failed: ${String(err)}\n`);
  process.exit(1);
});

